import java.util.ArrayList;
import java.util.List;

public class RecentItemsCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(RecentItemsFactory factory) {
        try {
            return RecentItemsChecker.isCorrect(factory);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(CorrectRecentItems::new));
        check("accepts an equally correct implementation", true, verdict(DequeRecentItems::new));
        check("rejects the keeps-one-too-many bug", false, verdict(OffByOneRecentItems::new));
        check("rejects the drops-the-newest bug", false, verdict(DropsNewestRecentItems::new));
        check("rejects the newest-first ordering bug", false, verdict(NewestFirstRecentItems::new));
        check("rejects the leaks-its-internal-list bug", false, verdict(LeakyRecentItems::new));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectRecentItems implements RecentItems {
    private final int capacity;
    private final List<String> kept = new ArrayList<>();

    CorrectRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        kept.add(item);
        while (kept.size() > capacity) {
            kept.remove(0);
        }
    }

    public List<String> items() {
        return new ArrayList<>(kept);
    }
}

class DequeRecentItems implements RecentItems {
    private final int capacity;
    private final java.util.ArrayDeque<String> kept = new java.util.ArrayDeque<>();

    DequeRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        if (kept.size() == capacity) {
            kept.removeFirst();
        }
        kept.addLast(item);
    }

    public List<String> items() {
        return new ArrayList<>(kept);
    }
}

class OffByOneRecentItems implements RecentItems {
    private final int capacity;
    private final List<String> kept = new ArrayList<>();

    OffByOneRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        kept.add(item);
        while (kept.size() > capacity + 1) {
            kept.remove(0);
        }
    }

    public List<String> items() {
        return new ArrayList<>(kept);
    }
}

class DropsNewestRecentItems implements RecentItems {
    private final int capacity;
    private final List<String> kept = new ArrayList<>();

    DropsNewestRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        if (kept.size() >= capacity) {
            return;
        }
        kept.add(item);
    }

    public List<String> items() {
        return new ArrayList<>(kept);
    }
}

class NewestFirstRecentItems implements RecentItems {
    private final int capacity;
    private final List<String> kept = new ArrayList<>();

    NewestFirstRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        kept.add(0, item);
        while (kept.size() > capacity) {
            kept.remove(kept.size() - 1);
        }
    }

    public List<String> items() {
        return new ArrayList<>(kept);
    }
}

class LeakyRecentItems implements RecentItems {
    private final int capacity;
    private final List<String> kept = new ArrayList<>();

    LeakyRecentItems(int capacity) {
        this.capacity = capacity;
    }

    public void add(String item) {
        kept.add(item);
        while (kept.size() > capacity) {
            kept.remove(0);
        }
    }

    public List<String> items() {
        return kept;
    }
}

