/**
 * TASK: Write the checks that decide whether a RecentItems buffer is correct.
 *
 * The RecentItems contract (a "last N things" list):
 *   add(item) appends an item. Once the buffer already holds `capacity` items,
 *   adding another one evicts the OLDEST.
 *   items() returns what is kept, oldest first and newest last, never more than
 *   capacity entries -- and it returns a SNAPSHOT: changing the returned list
 *   must not change the buffer.
 *   Example with capacity 3: add a, b, c, d  ->  items() is [b, c, d]
 *
 * You are handed a RecentItemsFactory rather than a single buffer, so you can
 * create as many buffers, at as many capacities, as your checks need.
 *
 * isCorrect(factory) must return true for a buffer that honours the contract
 * and false for one that does not. A crash counts as a failure, so wrap your
 * calls in try/catch and return false if anything is thrown.
 *
 * Adding fewer items than the capacity proves nothing -- every broken buffer
 * here looks fine until it is full, and one of them only misbehaves when the
 * caller edits the list it handed back.
 */
import java.util.List;

interface RecentItems {
    /* Provided -- do not edit. */
    void add(String item);

    java.util.List<String> items();
}

interface RecentItemsFactory {
    /* Provided -- do not edit. */
    RecentItems create(int capacity);
}

public class RecentItemsChecker {

    public static boolean isCorrect(RecentItemsFactory factory) {
        try {
            RecentItems buffer = factory.create(3);
            if (!buffer.items().toString().equals("[]")) {
                return false;
            }
            buffer.add("a");
            buffer.add("b");
            if (!buffer.items().toString().equals("[a, b]")) {
                return false;
            }
            buffer.add("c");
            buffer.add("d");
            if (!buffer.items().toString().equals("[b, c, d]")) {
                return false;
            }
            buffer.add("e");
            if (!buffer.items().toString().equals("[c, d, e]")) {
                return false;
            }

            RecentItems tiny = factory.create(1);
            tiny.add("x");
            tiny.add("y");
            if (!tiny.items().toString().equals("[y]")) {
                return false;
            }

            RecentItems leakTest = factory.create(3);
            leakTest.add("a");
            leakTest.add("b");
            List<String> snapshot = leakTest.items();
            snapshot.clear();
            if (!leakTest.items().toString().equals("[a, b]")) {
                return false;
            }
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
